const PAGE = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n<meta name=\"theme-color\" content=\"#04160f\" />\n<title>聚会/活动报名</title>\n<style>\n  :root{\n    --felt-1:#15523d; --felt-2:#0a3527; --felt-3:#04160f;\n    --gold:#e8c56a; --gold-2:#c9a24a;\n    --tile:#fbf7ec; --tile-edge:#cfc5aa;\n    --muted:rgba(255,255,255,.5);\n    --line:rgba(255,255,255,.1);\n  }\n  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n  html,body{margin:0;padding:0}\n  body{\n    font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif;\n    color:#fff;min-height:100vh;padding-bottom:112px;\n    background:radial-gradient(130% 90% at 50% -10%,var(--felt-1) 0%,var(--felt-2) 48%,var(--felt-3) 100%) fixed;\n  }\n  .wrap{max-width:480px;margin:0 auto;padding:22px 16px 0}\n\n  .hd{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}\n  .hd h1{font-size:20px;margin:0 0 7px;font-weight:700;letter-spacing:.4px}\n  .meta{font-size:13px;color:var(--muted);line-height:1.75}\n  .gear{background:rgba(255,255,255,.08);border:1px solid var(--line);color:#fff;width:38px;height:38px;\n        border-radius:12px;font-size:17px;cursor:pointer;flex:0 0 auto}\n  .badge{display:inline-block;font-size:11px;padding:2px 8px;border-radius:20px;margin-left:6px;\n         background:rgba(232,197,106,.16);color:var(--gold);vertical-align:2px}\n  .whoami{display:inline-flex;align-items:center;gap:7px;margin-top:10px;font-size:13px;color:#dfe9e3;\n          background:rgba(255,255,255,.07);border:1px solid var(--line);\n          padding:4px 12px 4px 5px;border-radius:22px;cursor:pointer;font-family:inherit}\n  .whoami .av{width:26px;height:26px;font-size:13px}\n\n  .tabs{display:flex;gap:6px;margin:16px 0 18px;background:rgba(0,0,0,.25);padding:4px;border-radius:13px}\n  .tab{flex:1;text-align:center;padding:9px 0;border-radius:10px;font-size:14px;\n       color:var(--muted);font-weight:600;cursor:pointer;transition:.18s}\n  .tab.on{background:rgba(255,255,255,.13);color:#fff}\n\n  .cd{display:flex;align-items:center;gap:8px;margin-bottom:16px;padding:11px 14px;border-radius:12px;\n      font-size:13px;background:rgba(232,197,106,.09);border:1px solid rgba(232,197,106,.26);color:var(--gold)}\n  .cd.urgent{background:rgba(226,94,94,.12);border-color:rgba(226,94,94,.32);color:#ff9b9b}\n  .cd.closed{background:rgba(255,255,255,.05);border-color:var(--line);color:var(--muted)}\n\n  .stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:20px}\n  .stat{background:rgba(255,255,255,.055);border:1px solid var(--line);border-radius:14px;\n        padding:12px 8px;text-align:center}\n  .stat b{display:block;font-size:23px;font-weight:800;letter-spacing:-.6px;line-height:1.25}\n  .stat span{font-size:11px;color:var(--muted)}\n\n  .tbl{background:rgba(255,255,255,.045);border:1px solid var(--line);border-radius:16px;\n       padding:14px;margin-bottom:12px;transition:.2s}\n  .tbl.full{background:linear-gradient(180deg,rgba(232,197,106,.10),rgba(255,255,255,.025));\n            border-color:rgba(232,197,106,.32)}\n  .tbl-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:11px}\n  .tbl-hd .name{font-size:14px;font-weight:700;letter-spacing:.6px}\n  .room-title{display:block;margin-top:4px;font-size:12px;font-weight:500;letter-spacing:0;color:var(--muted)}\n  .room-meta{display:flex;flex-wrap:wrap;gap:5px 12px;margin:-3px 0 10px;color:var(--muted);font-size:11px}\n  .room-cd{margin-bottom:10px;padding:7px 10px;font-size:11px}\n  .room-card.available{border-color:rgba(232,197,106,.5);box-shadow:0 0 0 1px rgba(232,197,106,.08),0 8px 24px rgba(0,0,0,.12)}\n  .room-action{margin-top:10px}\n  .room-join{width:100%;border:0;border-radius:11px;padding:12px 10px;background:linear-gradient(180deg,#f1d486,#d3a94f);\n             color:#2b1f05;font-family:inherit;font-size:15px;font-weight:700;cursor:pointer;box-shadow:0 5px 16px rgba(232,197,106,.2)}\n  .room-join:active{transform:scale(.985)}\n  .room-join.switch{background:rgba(232,197,106,.14);border:1px solid rgba(232,197,106,.38);color:var(--gold);box-shadow:none}\n  .room-join.muted{background:rgba(255,255,255,.06);border:1px solid var(--line);color:var(--muted);box-shadow:none;cursor:default}\n  .tbl-hd .st{font-size:11px;padding:3px 9px;border-radius:20px;background:rgba(255,255,255,.1);color:var(--muted)}\n  .tbl.full .st{background:rgba(232,197,106,.18);color:var(--gold)}\n  .seats{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n\n  .av{display:inline-grid;place-items:center;border-radius:50%;font-weight:800;color:#1b1b1b;\n      width:34px;height:34px;font-size:15px;flex:0 0 auto;overflow:hidden;line-height:1}\n  .seat{display:flex;align-items:center;gap:8px;background:var(--tile);color:#191919;border-radius:9px;\n        padding:8px 10px;font-size:14.5px;font-weight:700;min-width:0;\n        box-shadow:0 2px 0 var(--tile-edge),0 4px 10px rgba(0,0,0,.28)}\n  .seat .nm{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .seat.me{outline:2px solid var(--gold);outline-offset:-2px}\n  .seat.empty{background:transparent;color:rgba(255,255,255,.2);box-shadow:none;justify-content:center;\n              border:1.5px dashed rgba(255,255,255,.16);font-weight:400;font-size:13px;padding:11px 6px}\n  .tbl-switch{border:0;background:transparent;color:var(--gold);font:inherit;font-size:12px;cursor:pointer;padding:3px 0 3px 8px}\n  .add-room{width:100%;margin:0 0 12px;padding:13px;border:1px dashed rgba(255,255,255,.2);border-radius:14px;\n            background:rgba(255,255,255,.025);color:var(--muted);font-family:inherit;font-size:14px;font-weight:600;cursor:pointer}\n  .add-room:active{background:rgba(255,255,255,.08);color:#fff}\n  .bar.three .btn{font-size:14px;padding-left:7px;padding-right:7px}\n\n  .waitbox{background:rgba(255,255,255,.035);border:1px dashed rgba(255,255,255,.16);\n           border-radius:14px;padding:13px 14px;margin-bottom:12px}\n  .waitbox .t{font-size:12px;color:var(--muted);margin-bottom:8px}\n  .chips{display:flex;flex-wrap:wrap;gap:6px}\n  .chip{display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:3px 10px 3px 4px;\n        border-radius:20px;background:rgba(255,255,255,.1)}\n  .chip .av{width:20px;height:20px;font-size:10px}\n\n  .rank{background:rgba(255,255,255,.045);border:1px solid var(--line);border-radius:16px;overflow:hidden}\n  .row{display:flex;align-items:center;gap:10px;padding:12px 15px;border-bottom:1px solid var(--line)}\n  .row:last-child{border-bottom:0}\n  .no{width:20px;font-size:13px;color:var(--muted);font-weight:700;text-align:center}\n  .no.top{color:var(--gold)}\n  .nm2{flex:1;font-size:15px;font-weight:600;min-width:0}\n  .sub{font-size:11px;color:var(--muted);font-weight:400;margin-top:2px}\n  .score{font-size:17px;font-weight:800;font-variant-numeric:tabular-nums}\n  .pos{color:#7fe0ad}.neg{color:#ff9b9b}\n  .empty-tip{text-align:center;color:var(--muted);font-size:13px;padding:38px 10px;line-height:1.8}\n\n  .bar{position:fixed;left:0;right:0;bottom:0;z-index:20;display:flex;gap:10px;\n       max-width:480px;margin:0 auto;padding:12px 16px calc(12px + env(safe-area-inset-bottom));\n       background:linear-gradient(180deg,rgba(4,22,15,0),rgba(4,22,15,.92) 42%,#04160f 100%)}\n  .btn{flex:1;border:0;border-radius:13px;padding:15px 10px;font-size:16px;font-weight:700;\n       font-family:inherit;cursor:pointer;transition:transform .1s}\n  .btn:active{transform:scale(.975)}\n  .btn-primary{background:linear-gradient(180deg,#f1d486,#d3a94f);color:#2b1f05;\n               box-shadow:0 6px 20px rgba(232,197,106,.26)}\n  .btn-ghost{flex:.6;background:rgba(255,255,255,.09);color:#fff}\n  .btn-danger{background:rgba(219,84,84,.15);color:#ff9d9d;border:1px solid rgba(219,84,84,.34)}\n  .btn[disabled]{opacity:.45;cursor:default}\n  .wide{width:100%;margin-top:10px}\n\n  .mask{position:fixed;inset:0;z-index:60;display:flex;align-items:flex-end;justify-content:center;\n        background:rgba(0,0,0,.6);backdrop-filter:blur(6px)}\n  .sheet{width:100%;max-width:480px;background:#0d2b21;border-radius:20px 20px 0 0;\n         padding:22px 20px calc(22px + env(safe-area-inset-bottom));\n         animation:up .22s cubic-bezier(.2,.8,.3,1);max-height:88vh;overflow:auto}\n  @keyframes up{from{transform:translateY(40px);opacity:.5}to{transform:none;opacity:1}}\n  .sheet h3{margin:0 0 6px;font-size:17px}\n  .sheet p.hint{margin:0 0 16px;font-size:12.5px;color:var(--muted);line-height:1.7}\n  .field{margin-bottom:13px}\n  .field label{display:block;font-size:12px;color:var(--muted);margin-bottom:6px}\n  input,select,textarea{width:100%;background:rgba(255,255,255,.07);border:1px solid var(--line);color:#fff;\n               padding:12px;border-radius:11px;font-size:16px;font-family:inherit;outline:none}\n  input:focus,select:focus,textarea:focus{border-color:var(--gold-2)}\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n  .actions{display:flex;gap:10px;margin-top:18px}\n  .actions .btn{padding:14px 10px;font-size:15px}\n\n  .pick{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:8px 0 4px}\n  .pick-item{background:rgba(255,255,255,.06);border:1px solid var(--line);border-radius:14px;\n             padding:13px 6px;color:#fff;font-family:inherit;font-size:13px;display:flex;\n             flex-direction:column;align-items:center;gap:8px;cursor:pointer;min-width:0}\n  .pick-item:active{background:rgba(255,255,255,.14)}\n  .pick-item .nm3{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .av.lg{width:50px;height:50px;font-size:22px}\n\n  .row-edit{display:flex;align-items:center;gap:8px;margin-bottom:9px}\n  .row-edit .av{width:36px;height:36px;font-size:15px}\n  .row-edit input{flex:1;padding:10px;font-size:15px;min-width:0}\n  .row-edit select{width:64px;padding:9px 2px;font-size:16px;flex:0 0 auto}\n  .room-edit{display:flex;align-items:center;gap:8px;margin-bottom:9px}\n  .room-edit span{width:58px;flex:0 0 auto;font-size:13px;color:var(--muted)}\n  .room-edit input{flex:1;padding:10px;font-size:15px;min-width:0}\n  .room-config{margin:0 0 14px;padding:12px;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.035)}\n  .room-config-title{margin-bottom:10px;font-size:13px;font-weight:700;color:var(--gold)}\n  .room-config .field{margin-bottom:9px}\n  .del{background:rgba(219,84,84,.15);border:1px solid rgba(219,84,84,.3);color:#ff9d9d;\n       width:36px;height:36px;border-radius:10px;font-size:17px;cursor:pointer;flex:0 0 auto;font-family:inherit}\n\n  .list-item{display:flex;align-items:center;gap:9px;margin-bottom:9px}\n  .list-item input{width:76px;text-align:center;padding:9px 6px;font-size:15px;flex:0 0 auto}\n\n  .score-row{display:flex;align-items:center;gap:9px;padding:11px 12px;border:1px solid var(--line);\n             border-radius:13px;margin-bottom:9px;background:rgba(255,255,255,.04)}\n  .score-row .nm2{flex:1;min-width:0}\n  .badge2{font-size:11px;padding:3px 9px;border-radius:20px;background:rgba(255,255,255,.1);\n          color:var(--muted);white-space:nowrap;flex:0 0 auto}\n  .badge2.ok{background:rgba(127,224,173,.15);color:#7fe0ad}\n  .badge2.warn{background:rgba(255,155,155,.15);color:#ff9b9b}\n  .mini{flex:0 0 auto;border:0;border-radius:10px;padding:8px 12px;font-size:13px;font-weight:600;\n        font-family:inherit;cursor:pointer}\n  .mini.p{background:rgba(232,197,106,.16);color:var(--gold)}\n  .mini.d{background:rgba(219,84,84,.14);color:#ff9d9d}\n  .sumline{text-align:right;font-size:13px;color:var(--muted);margin-top:6px}\n  .sumline b{font-size:20px;color:#fff;font-variant-numeric:tabular-nums;margin-left:4px}\n  .sumline b.bad{color:#ff9b9b}\n  .sumline b.good{color:#7fe0ad}\n  .history-list{display:grid;gap:10px}\n  .history-card{padding:13px 14px;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.045)}\n  .history-head{display:flex;justify-content:space-between;gap:10px;font-size:13px}\n  .history-head b{margin-right:8px;color:var(--gold)}\n  .history-head span{color:var(--muted);font-size:11px}\n  .history-sub{margin-top:7px;color:var(--muted);font-size:12px;line-height:1.5}\n  .admin-badge{font-size:10px;padding:2px 6px;border-radius:10px;background:rgba(232,197,106,.18);color:var(--gold)}\n\n  .toast{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:99;\n         background:rgba(0,0,0,.82);padding:13px 22px;border-radius:12px;font-size:14px;\n         animation:fade .2s;pointer-events:none;max-width:80vw;text-align:center;line-height:1.6}\n  @keyframes fade{from{opacity:0}to{opacity:1}}\n</style>\n</head>\n<body>\n<div id=\"app\"></div>\n<script>\nconst ADMIN_NAME = '该隐cain';\n\nfunction rid(prefix) {\n  return prefix + Math.random().toString(36).slice(2, 8);\n}\n\nfunction avatarColor(name) {\n  const s = String(name || '?');\n  let h = 0;\n  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;\n  return 'hsl(' + h + ', 58%, 63%)';\n}\n\nfunction nextFridayCN(now = Date.now()) {\n  const d = new Date(now + 8 * 3600e3);\n  const add = (5 - d.getUTCDay() + 7) % 7;\n  const t = new Date(d.getTime());\n  t.setUTCDate(d.getUTCDate() + add);\n  t.setUTCHours(19, 30, 0, 0);\n  if (t.getTime() <= d.getTime()) t.setUTCDate(t.getUTCDate() + 7);\n  return t.getTime() - 8 * 3600e3;\n}\n\nfunction blankRoom(now = Date.now(), index = 1, defaults = {}) {\n  return {\n    id: rid('r'),\n    roomNo: String(index),\n    title: defaults.title || '活动报名',\n    venue: defaults.venue || '待定',\n    startAt: Number(defaults.startAt) || nextFridayCN(now),\n    durationMin: Number(defaults.durationMin) || 180,\n    deadlineMin: Number.isFinite(defaults.deadlineMin) ? defaults.deadlineMin : 120\n  };\n}\n\nfunction blankSession(now = Date.now()) {\n  return {\n    id: rid('s'),\n    rooms: [blankRoom(now, 1)],\n    capacity: 4,\n    players: []\n  };\n}\n\nfunction defaultState(now = Date.now()) {\n  return { members: [], session: blankSession(now), history: [], archivedRooms: [], updatedAt: now };\n}\n\nfunction cleanMembers(list) {\n  const out = [];\n  (Array.isArray(list) ? list : []).forEach(m => {\n    if (!m) return;\n    const name = String(m.name || '').trim().slice(0, 8);\n    if (!name) return;\n    out.push({\n      id: m.id || rid('m'),\n      name,\n      emoji: String(m.emoji || '').slice(0, 4),\n      color: m.color || avatarColor(name),\n      credit: m.credit == null ? 100 : Math.max(0, Math.min(100, Number(m.credit) || 0))\n    });\n  });\n  return out;\n}\n\nfunction cleanRooms(list, defaults = {}) {\n  return (Array.isArray(list) ? list : []).slice(0, 10).map((room, i) => ({\n    id: room && room.id ? room.id : rid('r'),\n    roomNo: String(room && (room.roomNo || room.name) || i + 1).trim().slice(0, 20) || String(i + 1),\n    title: String(room && room.title || defaults.title || '活动报名').trim().slice(0, 20) || '活动报名',\n    venue: String(room && room.venue || defaults.venue || '待定').trim().slice(0, 40) || '待定',\n    startAt: Number(room && room.startAt) || Number(defaults.startAt) || nextFridayCN(),\n    durationMin: Math.max(30, Math.min(720, Number(room && room.durationMin) || Number(defaults.durationMin) || 180)),\n    deadlineMin: Math.max(0, Math.min(2880, Number.isFinite(room && room.deadlineMin) ? room.deadlineMin : (Number.isFinite(defaults.deadlineMin) ? defaults.deadlineMin : 120))),\n    ...(Number(room && room.startedAt) ? { startedAt: Number(room.startedAt) } : {})\n  }));\n}\n\nfunction ensureRooms(session, now = Date.now()) {\n  if (Array.isArray(session.rooms) && session.rooms.length === 0) {\n    session.capacity = 0;\n    return [];\n  }\n\n  const raw = Array.isArray(session.rooms) ? session.rooms : [];\n  const rich = raw.some(room => room && (room.title || room.startAt || room.venue || room.durationMin));\n  if (!raw.length || !rich) {\n    const active = Array.isArray(session.players) ? session.players.filter(p => p && !p.cancelled) : [];\n    const legacyMax = active.reduce((max, p) => Math.max(max, Number(p.tableNo) || 0), 0);\n    const legacyCount = Math.max(1, Math.max(legacyMax, Math.ceil(active.length / 4)));\n    const count = Math.min(10, legacyCount);\n    const defaults = {\n      title: session.title,\n      venue: session.venue,\n      startAt: session.startAt,\n      deadlineMin: session.deadlineMin\n    };\n    session.rooms = Array.from({ length: count }, (_, i) => blankRoom(now, i + 1, defaults));\n    raw.forEach((room, i) => {\n      if (session.rooms[i] && room) {\n        if (room.name) session.rooms[i].roomNo = String(room.name).trim().slice(0, 20) || String(i + 1);\n        if (room.id) session.rooms[i].id = room.id;\n      }\n    });\n  } else {\n    session.rooms = cleanRooms(raw);\n  }\n  session.capacity = session.rooms.length * 4;\n  return session.rooms;\n}\n\nfunction roomEndAt(room) {\n  return Number(room.startAt) + Number(room.durationMin || 180) * 60000;\n}\n\nfunction deadlineOf(room) {\n  return Number(room.startAt) - Number(room.deadlineMin || 0) * 60000;\n}\n\nfunction normalizeRoomAssignments(session, now = Date.now()) {\n  const rooms = ensureRooms(session, now);\n  const occupied = new Map(rooms.map(room => [room.id, 0]));\n  session.players\n    .filter(p => !p.cancelled)\n    .sort((a, b) => (a.joinedAt || 0) - (b.joinedAt || 0))\n    .forEach(player => {\n      const room = rooms.find(item => item.id === player.roomId);\n      if (room && now >= roomEndAt(room)) return;\n      if (room && now < roomEndAt(room) && occupied.get(room.id) < 4) {\n        occupied.set(room.id, occupied.get(room.id) + 1);\n        return;\n      }\n      const next = rooms.find(item => now < roomEndAt(item) && occupied.get(item.id) < 4);\n      if (next) {\n        player.roomId = next.id;\n        occupied.set(next.id, occupied.get(next.id) + 1);\n      } else {\n        delete player.roomId;\n      }\n    });\n}\n\nfunction archiveEndedRooms(state, now = Date.now()) {\n  const session = state.session;\n  const rooms = ensureRooms(session, now);\n  const activeCount = room => session.players.filter(player => !player.cancelled && player.roomId === room.id).length;\n  const notStarted = rooms.filter(room => now >= room.startAt && !room.startedAt && activeCount(room) < 4);\n  rooms.forEach(room => {\n    if (now >= room.startAt && activeCount(room) >= 4) room.startedAt = room.startedAt || room.startAt;\n  });\n  const ended = rooms.filter(room => now >= roomEndAt(room) && room.startedAt);\n  const removeIds = new Set([...notStarted, ...ended].map(room => room.id));\n  if (!removeIds.size) return;\n  state.archivedRooms = Array.isArray(state.archivedRooms) ? state.archivedRooms : [];\n  ended.forEach(room => {\n    if (state.archivedRooms.some(item => item.id === room.id)) return;\n    state.archivedRooms.push({\n      ...room,\n      endedAt: roomEndAt(room),\n      players: session.players.filter(player => player.roomId === room.id),\n      results: state.history.filter(entry => entry.roomId === room.id)\n    });\n  });\n  session.rooms = rooms.filter(room => !removeIds.has(room.id));\n  session.players = session.players.filter(player => !removeIds.has(player.roomId));\n  session.capacity = session.rooms.length * 4;\n}\n\nfunction normalizeState(st, now = Date.now()) {\n  if (!st || typeof st !== 'object' || !st.session) return defaultState(now);\n\n  st.members = cleanMembers(st.members);\n  st.history = Array.isArray(st.history) ? st.history : [];\n  st.archivedRooms = Array.isArray(st.archivedRooms) ? st.archivedRooms : [];\n  st.session.players = Array.isArray(st.session.players) ? st.session.players : [];\n\n  const byName = name => st.members.find(member => member.name === name);\n  const make = name => {\n    const member = { id: rid('m'), name: String(name).slice(0, 8), emoji: '', color: avatarColor(name) };\n    st.members.push(member);\n    return member;\n  };\n\n  st.session.players = st.session.players.map(player => {\n    if (!player) return null;\n    if (player.memberId) return { ...player };\n    if (!player.name) return null;\n    const member = byName(player.name) || make(player.name);\n    return {\n      memberId: member.id,\n      roomId: player.roomId,\n      joinedAt: player.joinedAt || now,\n      cancelled: !!player.cancelled,\n      credit: player.credit == null ? 100 : player.credit\n    };\n  }).filter(Boolean);\n\n  const rooms = ensureRooms(st.session, now);\n  st.session.players.forEach(player => {\n    if (!player.roomId && player.tableNo) player.roomId = rooms[Number(player.tableNo) - 1]?.id;\n    delete player.tableNo;\n  });\n  normalizeRoomAssignments(st.session, now);\n\n  st.history = st.history.map(entry => {\n    if (!entry) return null;\n    const room = entry.roomId\n      ? rooms.find(item => item.id === entry.roomId)\n      : rooms[(Number(entry.tableNo) || 1) - 1];\n    return {\n      ...entry,\n      roomId: entry.roomId || (room && room.id) || '',\n      roomNo: entry.roomNo || (room && room.roomNo) || String(entry.tableNo || 1),\n      title: entry.title || (room && room.title) || '活动报名',\n      venue: entry.venue || (room && room.venue) || '待定',\n      startAt: entry.startAt || entry.date || (room && room.startAt) || now,\n      results: (Array.isArray(entry.results) ? entry.results : []).map(result => {\n        if (!result) return null;\n        if (result.memberId) return { memberId: result.memberId, score: Number(result.score) || 0 };\n        if (!result.name) return null;\n        const member = byName(result.name) || make(result.name);\n        return { memberId: member.id, score: Number(result.score) || 0 };\n      }).filter(Boolean)\n    };\n  }).filter(Boolean);\n\n  archiveEndedRooms(st, now);\n  st.members.forEach(member => {\n    if (member.credit == null) member.credit = 100;\n    st.session.players.forEach(player => {\n      if (player.memberId === member.id && player.credit != null && player.credit < member.credit) member.credit = player.credit;\n    });\n  });\n  return st;\n}\n\nfunction applyOp(state, op, now = Date.now()) {\n  normalizeState(state, now);\n  const session = state.session;\n  const type = op && op.t;\n  const members = Array.isArray(state.members) ? state.members : (state.members = []);\n  const rooms = () => ensureRooms(session, now);\n\n  if (type === 'members') {\n    state.members = cleanMembers(op.list);\n    const ids = new Set(state.members.map(member => member.id));\n    session.players = session.players.filter(player => ids.has(player.memberId));\n  } else if (type === 'join') {\n    const memberId = String(op.memberId || '');\n    const roomList = rooms();\n    const room = roomList.find(item => item.id === op.roomId) || roomList.find(item => now < deadlineOf(item));\n    if (members.some(member => member.id === memberId) && room && now < deadlineOf(room)) {\n      const existing = session.players.find(player => player.memberId === memberId && !player.cancelled);\n      const occupied = session.players.filter(player => !player.cancelled && player.roomId === room.id && player.memberId !== memberId).length;\n      if (!existing && occupied < 4) {\n        const old = session.players.find(player => player.memberId === memberId);\n        if (old) {\n          old.cancelled = false;\n          old.joinedAt = now;\n          old.roomId = room.id;\n        } else {\n          session.players.push({ memberId, roomId: room.id, joinedAt: now, cancelled: false });\n        }\n      }\n    }\n  } else if (type === 'move') {\n    const memberId = String(op.memberId || '');\n    const room = rooms().find(item => item.id === op.roomId);\n    const player = session.players.find(item => item.memberId === memberId && !item.cancelled);\n    const occupied = room ? session.players.filter(item => !item.cancelled && item.roomId === room.id && item.memberId !== memberId).length : 4;\n    if (player && room && now < deadlineOf(room) && occupied < 4) player.roomId = room.id;\n  } else if (type === 'leave') {\n    const player = session.players.find(item => item.memberId === op.memberId && !item.cancelled);\n    if (player) {\n      player.cancelled = true;\n      const room = rooms().find(item => item.id === player.roomId);\n      if (room && now > deadlineOf(room)) {\n        const member = members.find(item => item.id === op.memberId);\n        if (member) member.credit = Math.max(0, (member.credit == null ? 100 : member.credit) - 10);\n      }\n    }\n  } else if (type === 'settings') {\n    const patch = op.patch || {};\n    if (Array.isArray(patch.rooms)) session.rooms = cleanRooms(patch.rooms);\n    ensureRooms(session, now);\n    normalizeRoomAssignments(session, now);\n  } else if (type === 'score') {\n    const room = rooms().find(item => item.id === op.roomId)\n      || state.archivedRooms.find(item => item.id === op.roomId);\n    const results = (Array.isArray(op.results) ? op.results : [])\n      .filter(result => result && result.memberId)\n      .map(result => ({ memberId: result.memberId, score: Number(result.score) || 0 }));\n    if (room && results.length) {\n      state.history = state.history.filter(entry => !(entry.roomId === room.id));\n      const entry = {\n        id: op.id || rid('h'),\n        roomId: room.id,\n        roomNo: room.roomNo,\n        title: room.title,\n        venue: room.venue,\n        startAt: room.startAt,\n        results\n      };\n      state.history.push(entry);\n      const archived = state.archivedRooms.find(item => item.id === room.id);\n      if (archived) archived.results = [entry];\n    }\n  } else if (type === 'unscore') {\n    state.history = state.history.filter(entry => entry.id !== op.id);\n  } else if (type === 'delete-room') {\n    const actor = members.find(member => member.id === op.actorMemberId);\n    if (actor && actor.name === ADMIN_NAME && op.roomId) {\n      session.rooms = session.rooms.filter(room => room.id !== op.roomId);\n      session.players = session.players.filter(player => player.roomId !== op.roomId);\n      state.history = state.history.filter(entry => entry.roomId !== op.roomId);\n      state.archivedRooms = state.archivedRooms.filter(room => room.id !== op.roomId);\n      session.capacity = session.rooms.length * 4;\n    }\n  } else if (type === 'reset') {\n    state.prev = { session: JSON.parse(JSON.stringify(session)), at: now };\n    const fresh = blankSession(now);\n    fresh.rooms = rooms().map((room, i) => ({ ...room, id: rid('r'), startAt: nextFridayCN(now), roomNo: room.roomNo || String(i + 1) }));\n    fresh.capacity = fresh.rooms.length * 4;\n    state.session = fresh;\n  } else if (type === 'restore') {\n    if (state.prev && state.prev.session) {\n      state.session = state.prev.session;\n      state.prev = null;\n    }\n  }\n\n  normalizeState(state, now);\n  state.updatedAt = now;\n  return state;\n}\n\nfunction activePlayers(state) {\n  return state.session.players\n    .filter(player => !player.cancelled)\n    .sort((a, b) => a.joinedAt - b.joinedAt);\n}\n\nfunction memberOf(state, id) {\n  return (state.members || []).find(member => member.id === id) || null;\n}\n\n\n/* ===================== 本地状态 ===================== */\nconst LS_KEY = 'mj_signup_v1';\nconst GROUP = new URLSearchParams(location.search).get('g') || 'main';\nconst API_ORIGIN = location.hostname === 'cain0501.github.io'\n  ? 'https://majiang.zzljb520.workers.dev'\n  : '';\nlet ONLINE = false;\nlet S = loadState();\nlet tab = 'signup';\nlet modal = null;\nlet outbox = [];       // 还没成功发出去的动作，断网也不会丢\nlet flushing = false;\n\nfunction loadState(){\n  let raw = null;\n  try { raw = JSON.parse(localStorage.getItem(LS_KEY)); } catch (e) {}\n  const st = normalizeState(raw || defaultState());\n  st.memberId = (raw && raw.memberId) || null;\n  try { localStorage.setItem(LS_KEY, JSON.stringify(st)); } catch (e) {}\n  return st;\n}\nfunction save(){ try { localStorage.setItem(LS_KEY, JSON.stringify(S)); } catch (e) {} }\n\n/* ===================== 云端同步 ===================== */\nasync function apiGet(){\n  const r = await fetch(API_ORIGIN + '/api/state?g=' + encodeURIComponent(GROUP), { cache: 'no-store' });\n  if (!r.ok) throw new Error('no api');\n  return await r.json();\n}\nasync function apiOp(op){\n  const r = await fetch(API_ORIGIN + '/api/op?g=' + encodeURIComponent(GROUP), {\n    method: 'POST',\n    headers: { 'content-type': 'application/json' },\n    body: JSON.stringify(op)\n  });\n  if (!r.ok) throw new Error('op failed');\n  return await r.json();\n}\nfunction adopt(d){\n  S.members = d.members || [];\n  S.session = d.session;\n  S.history = d.history || [];\n  S.archivedRooms = d.archivedRooms || [];\n  S.updatedAt = d.updatedAt;\n  if (S.memberId && !memberOf(S, S.memberId)) S.memberId = null;\n  save();\n  render();\n  if (!S.memberId) askWho();\n}\n// 本地立刻生效，再把动作排队发给服务器。发失败就留着，下次自动重试。\nfunction commit(op){\n  applyOp(S, op, Date.now());\n  save();\n  render();\n  if (!ONLINE) return;\n  outbox.push(op);\n  flush();\n}\n\nasync function flush(){\n  if (flushing || !outbox.length) return;\n  flushing = true;\n  let last = null;\n  while (outbox.length){\n    try {\n      last = await apiOp(outbox[0]);\n      outbox.shift();\n    } catch (e) {\n      break; // 网络不好，留到下次\n    }\n  }\n  flushing = false;\n  if (last && !outbox.length) adopt(last);\n}\n\n/* ===================== 小工具 ===================== */\nconst pad = n => String(n).padStart(2, '0');\nconst WD = '日一二三四五六';\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;' }[c]));\n\nconst fmtDay = ts => { const d = new Date(ts); return `${d.getMonth()+1}月${d.getDate()}日 周${WD[d.getDay()]}`; };\nconst fmtHM = ts => { const d = new Date(ts); return `${pad(d.getHours())}:${pad(d.getMinutes())}`; };\nconst fmtFull = ts => `${fmtDay(ts)} ${fmtHM(ts)}`;\n\nconst av = m => (m && (m.emoji || m.name.slice(0, 1))) || '?';\nconst avHtml = (m, cls) => `<span class=\"av ${cls||''}\" style=\"background:${m ? m.color : '#555'}\">${esc(av(m))}</span>`;\nconst meM = () => (S.memberId ? memberOf(S, S.memberId) : null);\nconst isAdmin = () => meM() && meM().name === '该隐cain';\nconst mePlayer = () => S.session.players.find(p => p.memberId === S.memberId && !p.cancelled) || null;\nconst roomCount = state => Math.min(10, Array.isArray(state.session.rooms) ? state.session.rooms.length : 0);\nconst roomName = (state, index) => {\n  const room = state.session.rooms && state.session.rooms[index];\n  const value = String(room && room.roomNo || '').trim();\n  return !value || value === String(index + 1) ? `房间 ${index + 1}` : value;\n};\nconst roomOf = (state, id) => (state.session.rooms || []).find(room => room.id === id) || null;\nconst roomRecordOf = (state, id) => roomOf(state, id) || (state.archivedRooms || []).find(room => room.id === id) || null;\nconst playersForRoom = (state, room) => activePlayers(state).filter(player => player.roomId === room.id);\nconst roomNoOf = player => {\n  const index = (S.session.rooms || []).findIndex(room => room.id === (player && player.roomId));\n  return index < 0 ? 0 : index + 1;\n};\nconst seated = () => activePlayers(S).filter(player => roomOf(S, player.roomId));\nconst waiting = () => activePlayers(S).filter(player => !roomOf(S, player.roomId));\nconst roomGroups = state => {\n  const assigned = activePlayers(state).filter(player => roomOf(state, player.roomId));\n  return Array.from({ length: roomCount(state) }, (_, i) =>\n    assigned.filter(player => player.roomId === state.session.rooms[i].id)\n  );\n};\nconst toLocalInput = ts => { const d = new Date(ts); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`; };\nconst roomStatus = (room, now = Date.now()) => {\n  if (now >= roomEndAt(room)) return { cls: 'closed', text: '已结束' };\n  if (now >= room.startAt) return { cls: 'urgent', text: `进行中 · ${fmtHM(roomEndAt(room))} 结束` };\n  if (now >= deadlineOf(room)) return { cls: 'closed', text: '报名已截止' };\n  const left = deadlineOf(room) - now;\n  const h = Math.floor(left / 3600000), m = Math.floor((left % 3600000) / 60000);\n  return { cls: left < 3600000 ? 'urgent' : '', text: `报名截止 ${fmtHM(deadlineOf(room))} · 还剩 ${h > 0 ? h + ' 小时 ' + m + ' 分' : m + ' 分钟'}` };\n};\n\nfunction toast(msg){\n  const el = document.createElement('div');\n  el.className = 'toast';\n  el.textContent = msg;\n  document.body.appendChild(el);\n  setTimeout(() => el.remove(), 1700);\n}\n\n/* ===================== 渲染 ===================== */\nconst app = document.getElementById('app');\n\nfunction render(){\n  const s = S.session;\n  const all = activePlayers(S);\n  const waitList = waiting();\n  const rooms = s.rooms || [];\n  const groups = roomGroups(S);\n  const openSeats = groups.reduce((sum, roomPlayers) => sum + (4 - roomPlayers.length), 0);\n  const me = meM();\n  const joined = !!mePlayer();\n  const currentRoom = mePlayer() ? roomOf(S, mePlayer().roomId) : null;\n\n  const now = Date.now();\n  let roomsHtml = '';\n  rooms.forEach((room, i) => {\n    const players = groups[i] || [];\n    const full = players.length === 4;\n    const status = roomStatus(room, now);\n    const mine = currentRoom && currentRoom.id === room.id;\n    const canJoin = !joined && now < deadlineOf(room) && now < roomEndAt(room) && !full;\n    const canMove = joined && !mine && now < deadlineOf(room) && now < roomEndAt(room) && !full;\n    let seats = '';\n    for (let k = 0; k < 4; k++){\n      const p = players[k];\n      const m = p ? memberOf(S, p.memberId) : null;\n      if (p && m){\n        seats += `<div class=\"seat${m.id === S.memberId ? ' me' : ''}\">${avHtml(m)}<span class=\"nm\">${esc(m.name)}</span></div>`;\n      } else {\n        seats += `<div class=\"seat empty\">${k === players.length ? '下一位' : '虚位'}</div>`;\n      }\n    }\n    const editButton = `<button class=\"tbl-switch\" data-act=\"edit-room\" data-id=\"${room.id}\">编辑</button>`;\n    const available = (!joined && !!me && canJoin) || canMove;\n    const action = mine\n      ? '<span class=\"badge2 ok\">当前房间</span>'\n      : `<span class=\"badge2\">${full ? '已满' : status.text === '报名已截止' || status.text === '已结束' ? status.text : ''}</span>`;\n    const roomButton = mine\n      ? '<div class=\"room-action\"><div class=\"room-join muted\">你已报名这个房间</div></div>'\n      : canJoin\n        ? `<div class=\"room-action\"><button class=\"room-join\" data-act=\"join-room\" data-id=\"${room.id}\">报名此房间</button></div>`\n        : canMove\n          ? `<div class=\"room-action\"><button class=\"room-join switch\" data-act=\"move-to\" data-id=\"${room.id}\">换到这个房间</button></div>`\n          : !joined && !me && now < deadlineOf(room) && now < roomEndAt(room)\n            ? '<div class=\"room-action\"><button class=\"room-join muted\" data-act=\"who\">先选择身份，再报名</button></div>'\n            : '';\n    roomsHtml += `<div class=\"tbl room-card${full ? ' full' : ''}${available ? ' available' : ''}\">\n        <div class=\"tbl-hd\">\n          <div class=\"name\">${esc(roomName(S, i))}<span class=\"room-title\">${esc(room.title)}</span></div>\n          <div><span class=\"st\">${players.length}/4${full ? ' · 已满' : ' · 还差 ' + (4 - players.length)}</span>${editButton}${action}</div>\n        </div>\n        <div class=\"room-meta\"><span>📍 ${esc(room.venue)}</span><span>🕐 ${fmtFull(room.startAt)}</span><span>⏱ ${room.durationMin} 分钟</span></div>\n        <div class=\"cd room-cd ${status.cls}\">${status.text}</div>\n        <div class=\"seats\">${seats}</div>\n        ${roomButton}\n      </div>`;\n  });\n\n  let waitHtml = '';\n  if (waitList.length){\n    waitHtml = `<div class=\"waitbox\">\n      <div class=\"t\">候补 ${waitList.length} 人（当前开放 ${roomCount(S)} 个房间，去 ⚙ 里调整房间数量）</div>\n      <div class=\"chips\">${waitList.map(p => {\n        const m = memberOf(S, p.memberId);\n        return m ? `<span class=\"chip\">${avHtml(m)}${esc(m.name)}</span>` : '';\n      }).join('')}</div>\n    </div>`;\n  }\n  const addRoomHtml = roomCount(S) < 10\n    ? '<button class=\"add-room\" data-act=\"add-room\">＋ 添加房间</button>'\n    : '';\n  const pendingArchiveHtml = (S.archivedRooms || [])\n    .filter(room => !(room.results || []).length)\n    .sort((a, b) => b.endedAt - a.endedAt)\n    .map(room => {\n      const players = room.players || [];\n      const names = players.map(player => memberOf(S, player.memberId)).filter(Boolean);\n      return `<div class=\"tbl room-card full archived-pending\">\n        <div class=\"tbl-hd\"><div class=\"name\">${esc(room.roomNo)}<span class=\"room-title\">${esc(room.title)}</span></div><span class=\"badge2 warn\">本局已结束</span></div>\n        <div class=\"room-meta\"><span>📍 ${esc(room.venue)}</span><span>🕐 ${fmtFull(room.startAt)}</span><span>⏱ ${room.durationMin} 分钟</span></div>\n        <div class=\"seats\">${Array.from({ length: 4 }, (_, i) => names[i]\n          ? `<div class=\"seat\">${avHtml(names[i])}<span class=\"nm\">${esc(names[i].name)}</span></div>`\n          : '<div class=\"seat empty\">空位</div>').join('')}</div>\n        <button class=\"btn btn-primary wide\" data-act=\"score-room\" data-id=\"${room.id}\">记录本局分数</button>\n        ${isAdmin() ? `<button class=\"mini d wide history-delete\" data-act=\"delete-room\" data-id=\"${room.id}\">删除这个房间</button>` : ''}\n      </div>`;\n    }).join('');\n\n  /* 排行 */\n  const rankList = buildRank();\n  let rankHtml;\n  if (!S.members.length){\n    rankHtml = `<div class=\"empty-tip\">还没有成员名单<br>点右上角 ⚙ → 成员管理，先把群里的 13 个人建好</div>`;\n  } else if (!rankList.some(r => r.games > 0)){\n    rankHtml = `<div class=\"empty-tip\">还没有战绩<br>打完一局，点右上角 ⚙ 记分就会出现在这里</div>`;\n  } else {\n    rankHtml = '<div class=\"rank\">' + rankList.filter(r => r.games > 0 || r.credit < 100).map((r, i) => `\n      <div class=\"row\">\n        <div class=\"no${i < 3 ? ' top' : ''}\">${i + 1}</div>\n        ${avHtml(r.m)}\n        <div class=\"nm2\">${esc(r.m.name)}<div class=\"sub\">${r.games} 局 · 胜率 ${r.games ? Math.round(r.wins / r.games * 100) : 0}% · 信用 ${r.credit}</div></div>\n        <div class=\"score ${r.total >= 0 ? 'pos' : 'neg'}\">${r.total > 0 ? '+' : ''}${r.total}</div>\n      </div>`).join('') + '</div>';\n  }\n\n  /* 底部按钮：报名会截止，但退出永远可以点 */\n  let btnLabel, btnCls, disabled = false;\n  if (joined){ btnLabel = '取消报名'; btnCls = 'btn btn-danger'; }\n  else if (!me){ btnLabel = '先选你是谁'; btnCls = 'btn btn-primary'; }\n  else { btnLabel = '请在房间卡片报名'; btnCls = 'btn btn-ghost'; disabled = true; }\n\n  const whoHtml = me\n    ? `<div class=\"whoami\" data-act=\"who\">${avHtml(me)}<span>${esc(me.name)}</span>${isAdmin() ? '<span class=\"admin-badge\">管理员</span>' : ''}<span style=\"opacity:.5\">· 切换</span></div>`\n    : `<div class=\"whoami\" data-act=\"who\"><span style=\"padding-left:8px\">👤 还没选你是谁</span></div>`;\n\n  app.innerHTML = `\n    <div class=\"wrap\">\n      <div class=\"hd\">\n        <div>\n          <h1>聚会/活动报名</h1>\n          <div class=\"meta\">当前开放 ${rooms.length} 个房间 · 每个房间最多 4 人<br>${currentRoom ? `你已报名：${esc(roomName(S, rooms.indexOf(currentRoom)))}` : '请选择一个房间报名'}</div>\n          ${whoHtml}\n        </div>\n        <button class=\"gear\" data-act=\"settings\">⚙</button>\n      </div>\n\n      <div class=\"tabs\">\n        <div class=\"tab ${tab === 'signup' ? 'on' : ''}\" data-act=\"tab\" data-tab=\"signup\">报名</div>\n        <div class=\"tab ${tab === 'rank' ? 'on' : ''}\" data-act=\"tab\" data-tab=\"rank\">排行</div>\n        <div class=\"tab ${tab === 'history' ? 'on' : ''}\" data-act=\"tab\" data-tab=\"history\">历史</div>\n      </div>\n\n      ${tab === 'signup' ? `\n        <div class=\"stats\">\n          <div class=\"stat\"><b>${all.length}</b><span>已报名</span></div>\n          <div class=\"stat\"><b>${groups.filter(roomPlayers => roomPlayers.length === 4).length}</b><span>已满的房间</span></div>\n          <div class=\"stat\"><b>${waitList.length || openSeats}</b><span>${waitList.length ? '候补人数' : '剩余空位'}</span></div>\n        </div>\n        ${roomsHtml}\n        ${pendingArchiveHtml}\n        ${addRoomHtml}\n        ${waitHtml}\n      ` : tab === 'rank' ? rankHtml : historyHtml()}\n    </div>\n\n    <div class=\"bar${joined ? ' three' : ''}\">\n      <button class=\"btn btn-ghost\" data-act=\"share\">复制文案</button>\n      ${joined ? '<button class=\"btn btn-ghost\" data-act=\"move-table\">换房间</button>' : ''}\n      <button class=\"${btnCls}\" data-act=\"toggle\" ${disabled ? 'disabled' : ''}>${btnLabel}</button>\n    </div>`;\n}\n\nfunction buildRank(){\n  const map = new Map();\n  const put = id => {\n    if (!map.has(id)) map.set(id, { id, games: 0, total: 0, wins: 0 });\n    return map.get(id);\n  };\n  S.members.forEach(m => put(m.id));\n  (S.history || []).forEach(h => (h.results || []).forEach(r => {\n    const e = put(r.memberId);\n    e.games++;\n    e.total += r.score;\n    if (r.score > 0) e.wins++;\n  }));\n  return [...map.values()]\n    .map(e => {\n      const m = memberOf(S, e.id);\n      return { ...e, m, credit: m && m.credit != null ? m.credit : 100 };\n    })\n    .filter(e => e.m)\n    .sort((a, b) => b.total - a.total || b.games - a.games);\n}\n\n/* 本局已经录过的房间 */\nfunction entryOf(roomId){\n  return (S.history || []).find(h => h.roomId === roomId) || null;\n}\n\nfunction historyHtml(){\n  const archived = Array.isArray(S.archivedRooms) ? [...S.archivedRooms].sort((a, b) => b.endedAt - a.endedAt) : [];\n  if (!archived.length) return '<div class=\"empty-tip\">还没有已结束的房间</div>';\n  return '<div class=\"history-list\">' + archived.map(room => {\n    const names = (room.players || []).map(player => (memberOf(S, player.memberId) || {}).name).filter(Boolean).join('、');\n    const result = (room.results || [])[0];\n    const total = result ? result.results.reduce((sum, item) => sum + item.score, 0) : null;\n    return `<div class=\"history-card\">\n      <div class=\"history-head\"><div><b>${esc(room.roomNo || '房间')}</b><span>${esc(room.title)}</span></div><span>${fmtFull(room.startAt)}</span></div>\n      <div class=\"history-sub\">📍 ${esc(room.venue)} · ${room.durationMin} 分钟 · ${esc(names || '无人报名')}</div>\n      <div class=\"history-sub\">${result ? `已记录成绩 · 合计 ${total > 0 ? '+' : ''}${total}` : '尚未记录成绩'}</div>\n       ${!result ? `<button class=\"btn btn-primary wide\" data-act=\"score-room\" data-id=\"${room.id}\">记录本局分数</button>` : ''}\n       ${isAdmin() ? `<button class=\"mini d history-delete\" data-act=\"delete-room\" data-id=\"${room.id}\">删除记录</button>` : ''}\n    </div>`;\n  }).join('') + '</div>';\n}\n\n/* ===================== 弹层 ===================== */\nconst EMOJIS = ['', '🀄', '🀅', '🐯', '🐼', '🦊', '🐷', '🐵', '🐶', '🐱', '🦁', '🐸', '🐔', '🦉',\n                '🍺', '🍉', '🍜', '🎩', '👑', '🃏', '🎲', '🎯', '😎', '🤠', '👻', '⭐', '🔥', '💎'];\n\nfunction sheet(inner){\n  return `<div class=\"mask\" data-act=\"mask\"><div class=\"sheet\">${inner}</div></div>`;\n}\n\n/* 记分时实时算合计，不归零就把按钮文案改掉 */\nfunction updateSum(){\n  const inputs = [...document.querySelectorAll('[data-score]')];\n  if (!inputs.length) return;\n  const sum = inputs.reduce((a, i) => a + (parseInt(i.value, 10) || 0), 0);\n  const el = document.getElementById('sum');\n  const btn = document.getElementById('save-score-btn');\n  if (el){ el.textContent = (sum > 0 ? '+' : '') + sum; el.className = sum === 0 ? 'good' : 'bad'; }\n  if (btn) btn.textContent = sum === 0 ? '存进战绩' : `合计 ${sum > 0 ? '+' : ''}${sum}，仍然保存`;\n}\n\nfunction renderModal(){\n  const old = document.querySelector('.mask');\n  if (old) old.remove();\n  if (!modal) return;\n\n  let html = '';\n\n  if (modal.type === 'who'){\n    const list = S.members;\n    html = sheet(`\n      <h3>你是哪位？</h3>\n      <p class=\"hint\">点一下自己就行。以后打开这个链接，自动就认得你了，不用再选。</p>\n      ${list.length\n        ? `<div class=\"pick\">${list.map(m => `\n            <button class=\"pick-item\" data-act=\"pick\" data-id=\"${m.id}\">\n              ${avHtml(m, 'lg')}<span class=\"nm3\">${esc(m.name)}</span>\n            </button>`).join('')}</div>`\n        : `<div class=\"empty-tip\" style=\"padding:22px 10px\">还没有成员名单。<br>先让群主把 13 个人建好，或者你自己加一个。</div>`}\n      <button class=\"btn btn-ghost wide\" data-act=\"add-self\">＋ 不在名单里，加我一个</button>\n      <button class=\"btn btn-ghost wide\" data-act=\"roster\" style=\"background:transparent;border:1px solid var(--line)\">管理成员名单</button>\n    `);\n  }\n  else if (modal.type === 'roster'){\n    html = sheet(`\n      <h3>成员名单</h3>\n      <p class=\"hint\">把群里 13 个人都建好，报名时大家只从这里面选，名字不会乱，排行榜也准。</p>\n      ${modal.list.map((m, i) => `\n        <div class=\"row-edit\" data-row=\"${i}\">\n          ${avHtml(m)}\n          <input data-name value=\"${esc(m.name)}\" maxlength=\"8\" placeholder=\"名字\">\n          <select data-emoji>${EMOJIS.map(e => `<option value=\"${e}\"${e === (m.emoji || '') ? ' selected' : ''}>${e || '字'}</option>`).join('')}</select>\n          <button class=\"del\" data-act=\"roster-del\" data-i=\"${i}\">×</button>\n        </div>`).join('')}\n      <button class=\"btn btn-ghost wide\" data-act=\"roster-add\">＋ 添加成员</button>\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" data-act=\"close\">取消</button>\n        <button class=\"btn btn-primary\" data-act=\"roster-save\">保存名单</button>\n      </div>`);\n  }\n  else if (modal.type === 'addself'){\n    html = sheet(`\n      <h3>加一个自己</h3>\n      <p class=\"hint\">名字最多 8 个字。加完会进入成员名单，别人也能看到。</p>\n      <div class=\"field\"><input id=\"in-name\" maxlength=\"8\" placeholder=\"比如：老王\"></div>\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" data-act=\"close\">取消</button>\n        <button class=\"btn btn-primary\" data-act=\"addself-ok\">加上</button>\n      </div>`);\n  }\n  else if (modal.type === 'confirm'){\n    html = sheet(`\n      <h3>${esc(modal.title)}</h3>\n      <p class=\"hint\">${esc(modal.desc)}</p>\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" data-act=\"close\">算了</button>\n        <button class=\"btn ${modal.danger ? 'btn-danger' : 'btn-primary'}\" data-act=\"confirm-ok\">${esc(modal.okText || '确定')}</button>\n      </div>`);\n  }\n  else if (modal.type === 'room-edit'){\n    const room = roomOf(S, modal.roomId);\n    if (!room) { modal = null; return; }\n    html = sheet(`\n      <h3>编辑 ${esc(roomName(S, S.session.rooms.indexOf(room)))}</h3>\n      <p class=\"hint\">只会修改这个房间，不影响其他房间。</p>\n      <div class=\"field\"><label>房间号</label><input id=\"edit-room-no\" value=\"${esc(room.roomNo)}\" maxlength=\"20\" placeholder=\"例如 A101\"></div>\n      <div class=\"field\"><label>标题</label><input id=\"edit-room-title\" value=\"${esc(room.title)}\" maxlength=\"20\"></div>\n      <div class=\"field\"><label>地点</label><input id=\"edit-room-venue\" value=\"${esc(room.venue)}\" maxlength=\"40\"></div>\n      <div class=\"grid2\">\n        <div class=\"field\"><label>开打时间</label><input id=\"edit-room-start\" type=\"datetime-local\" value=\"${toLocalInput(room.startAt)}\"></div>\n        <div class=\"field\"><label>开打时长（分钟）</label><input id=\"edit-room-duration\" type=\"number\" min=\"30\" max=\"720\" value=\"${room.durationMin}\"></div>\n      </div>\n      <div class=\"field\"><label>提前几小时截止报名</label><input id=\"edit-room-deadline\" type=\"number\" min=\"0\" max=\"48\" value=\"${room.deadlineMin / 60}\"></div>\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" data-act=\"close\">取消</button>\n        <button class=\"btn btn-primary\" data-act=\"save-room-edit\">保存</button>\n      </div>\n      ${isAdmin() ? `<button class=\"mini d wide history-delete\" data-act=\"delete-room\" data-id=\"${room.id}\">删除这个房间及其数据</button>` : ''}`);\n  }\n  else if (modal.type === 'move'){\n    const currentId = mePlayer() && mePlayer().roomId;\n    const rooms = S.session.rooms || [];\n    html = sheet(`\n      <h3>换到哪个房间？</h3>\n      <p class=\"hint\">只能换到有空位的房间，换房间不会影响报名时间和信用分。</p>\n      ${rooms.map((room, i) => {\n        const players = activePlayers(S).filter(player => player.roomId === room.id);\n        const full = players.length >= 4;\n        const mine = room.id === currentId;\n        const closed = Date.now() >= deadlineOf(room) || Date.now() >= roomEndAt(room);\n        return `<button class=\"btn btn-ghost wide\" data-act=\"move-to\" data-id=\"${room.id}\" ${full || mine || closed ? 'disabled' : ''}>\n          ${esc(roomName(S, i))} · ${esc(room.title)} · ${players.length}/4${mine ? ' · 当前房间' : full ? ' · 已满' : closed ? ' · 已截止' : ' · 换到这里'}\n        </button>`;\n      }).join('')}\n      <div class=\"actions\"><button class=\"btn btn-ghost\" data-act=\"close\">先不换</button></div>`);\n  }\n  else if (modal.type === 'settings'){\n    const s = S.session;\n    html = sheet(`\n      <h3>房间设置</h3>\n      <p class=\"hint\">每个房间独立设置房号、标题、地点、开始时间和时长。时间结束后，房间会自动归档到历史。</p>\n      ${(s.rooms || []).map((room, i) => `<div class=\"room-config\">\n        <div class=\"room-config-title\">房间 ${i + 1}</div>\n        <div class=\"grid2\">\n          <div class=\"field\"><label>房间号</label><input data-room-no=\"${i}\" value=\"${esc(room.roomNo)}\" maxlength=\"20\" placeholder=\"例如 A101\"></div>\n          <div class=\"field\"><label>标题</label><input data-room-title=\"${i}\" value=\"${esc(room.title)}\" maxlength=\"20\"></div>\n        </div>\n        <div class=\"field\"><label>地点</label><input data-room-venue=\"${i}\" value=\"${esc(room.venue)}\" maxlength=\"40\"></div>\n        <div class=\"grid2\">\n          <div class=\"field\"><label>开打时间</label><input data-room-start=\"${i}\" type=\"datetime-local\" value=\"${toLocalInput(room.startAt)}\"></div>\n          <div class=\"field\"><label>开打时长（分钟）</label><input data-room-duration=\"${i}\" type=\"number\" min=\"30\" max=\"720\" value=\"${room.durationMin}\"></div>\n        </div>\n        <div class=\"field\"><label>提前几小时截止报名</label><input data-room-deadline=\"${i}\" type=\"number\" min=\"0\" max=\"48\" value=\"${room.deadlineMin / 60}\"></div>\n      </div>`).join('')}\n      ${roomCount(S) < 10 ? '<button class=\"btn btn-ghost wide\" data-act=\"add-room\">＋ 添加房间</button>' : ''}\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" data-act=\"close\">取消</button>\n        <button class=\"btn btn-primary\" data-act=\"save-settings\">保存</button>\n      </div>\n      <button class=\"btn btn-ghost wide\" data-act=\"roster\">成员管理（${S.members.length} 人）</button>\n      <div class=\"actions\" style=\"margin-top:10px\">\n        <button class=\"btn btn-ghost\" data-act=\"open-score\" style=\"flex:1;background:rgba(232,197,106,.12);color:#e8c56a\">房间记分</button>\n      </div>`);\n  }\n  else if (modal.type === 'scores'){\n    const rooms = S.session.rooms || [];\n    html = sheet(`\n      <h3>房间记分</h3>\n      <p class=\"hint\">一个房间一条记录。四个人的分加起来应该是 0，不是 0 会提醒你，但照样能存。</p>\n      ${rooms.length ? rooms.map((room, i) => {\n        const players = activePlayers(S).filter(player => player.roomId === room.id);\n        const e = entryOf(room.id);\n        const sum = e ? e.results.reduce((a, r) => a + r.score, 0) : 0;\n        const names = players.map(p => (memberOf(S, p.memberId) || {}).name).filter(Boolean).join('、');\n        return `<div class=\"score-row\">\n          <div class=\"nm2\">${esc(roomName(S, i))} · ${esc(room.title)}<div class=\"sub\">${esc(names || '暂无报名')}</div></div>\n          ${e\n            ? `<span class=\"badge2 ${sum === 0 ? 'ok' : 'warn'}\">合计 ${sum > 0 ? '+' : ''}${sum}</span>\n               <button class=\"mini p\" data-act=\"score-table\" data-id=\"${room.id}\">改</button>\n               <button class=\"mini d\" data-act=\"unscore\" data-id=\"${e.id}\">删</button>`\n            : `<span class=\"badge2\">未录</span>\n               <button class=\"mini p\" data-act=\"score-table\" data-id=\"${room.id}\">录入</button>`}\n        </div>`;\n      }).join('') : `<div class=\"empty-tip\" style=\"padding:24px 10px\">还没人报名，先等人齐了再记分</div>`}\n      <div class=\"actions\"><button class=\"btn btn-ghost\" data-act=\"close\">关闭</button></div>`);\n  }\n  else if (modal.type === 'score'){\n    const room = roomRecordOf(S, modal.roomId);\n    const t = room\n      ? (roomOf(S, room.id) ? playersForRoom(S, room) : (room.players || []).filter(player => !player.cancelled))\n      : [];\n    const e = room ? entryOf(room.id) : null;\n    html = sheet(`\n      <h3>${esc(room ? room.roomNo : '房间')} · 录入成绩</h3>\n      <p class=\"hint\">填输赢分，赢为正、输为负，比如 +120 / -40。四个人加起来最好是 0。</p>\n      ${t.map((p, i) => {\n        const m = memberOf(S, p.memberId);\n        if (!m) return '';\n        const old = e ? e.results.find(r => r.memberId === p.memberId) : null;\n        return `<div class=\"list-item\">${avHtml(m)}<div class=\"nm2\">${esc(m.name)}</div>\n          <input type=\"number\" data-score=\"${i}\" value=\"${old ? old.score : 0}\" inputmode=\"numeric\"></div>`;\n      }).join('')}\n      <div class=\"sumline\">合计<b id=\"sum\" class=\"good\">0</b></div>\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" data-act=\"close-scores\">取消</button>\n        <button class=\"btn btn-primary\" data-act=\"save-score\" id=\"save-score-btn\">存进战绩</button>\n      </div>`);\n    setTimeout(updateSum, 0);\n  }\n  else if (modal.type === 'share'){\n    html = sheet(`\n      <h3>发到群里</h3>\n      <p class=\"hint\">点「复制」然后粘到微信群。</p>\n      <div class=\"field\"><textarea id=\"share-txt\" style=\"height:130px;line-height:1.8;font-size:14px\">${esc(modal.text)}</textarea></div>\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" data-act=\"close\">关掉</button>\n        <button class=\"btn btn-primary\" data-act=\"copy-share\">复制</button>\n      </div>`);\n  }\n\n  document.body.insertAdjacentHTML('beforeend', html);\n}\n\nfunction askWho(){\n  if (!S.members.length && modal && modal.type === 'who') return;\n  modal = { type: 'who' };\n  renderModal();\n}\n\nfunction syncRoster(){\n  if (!modal || modal.type !== 'roster') return;\n  modal.list = modal.list.map((m, i) => {\n    const row = document.querySelector('[data-row=\"' + i + '\"]');\n    if (!row) return m;\n    const name = row.querySelector('[data-name]').value;\n    const emoji = row.querySelector('[data-emoji]').value;\n    return { ...m, name, emoji, color: m.color || avatarColor(name || '?') };\n  });\n}\n\n/* ===================== 交互 ===================== */\ndocument.addEventListener('click', e => {\n  const el = e.target.closest('[data-act]');\n  if (!el) return;\n  const act = el.dataset.act;\n\n  if (act === 'tab'){ tab = el.dataset.tab; render(); return; }\n  if (act === 'close'){ modal = null; renderModal(); return; }\n  if (act === 'mask'){\n    if (e.target === el && modal && modal.type !== 'who'){ modal = null; renderModal(); }\n    return;\n  }\n\n  if (act === 'who'){ askWho(); return; }\n\n  if (act === 'add-room'){\n    if (roomCount(S) >= 10){ toast('最多添加 10 个房间'); return; }\n    const rooms = (S.session.rooms || []).map(room => ({ ...room }));\n    rooms.push(blankRoom(Date.now(), rooms.length + 1));\n    commit({ t: 'settings', patch: { rooms } });\n    if (modal && modal.type === 'settings') renderModal();\n    toast('已添加房间');\n    return;\n  }\n\n  if (act === 'join-room'){\n    if (!meM()){ askWho(); return; }\n    if (mePlayer()){ toast('你已经报名了一个房间'); return; }\n    commit({ t: 'join', memberId: S.memberId, roomId: el.dataset.id });\n    toast('报名成功');\n    return;\n  }\n\n  if (act === 'edit-room'){\n    modal = { type: 'room-edit', roomId: el.dataset.id };\n    renderModal();\n    return;\n  }\n\n  if (act === 'delete-room'){\n    if (!isAdmin()) { toast('只有该隐cain可以删除数据'); return; }\n    const roomId = el.dataset.id;\n    modal = {\n      type: 'confirm',\n      title: '删除这个房间？',\n      desc: '房间、报名记录、成绩和历史记录都会删除，删除后不能恢复。',\n      okText: '确认删除',\n      danger: true,\n      onOk: () => {\n        modal = null;\n        renderModal();\n        commit({ t: 'delete-room', roomId, actorMemberId: S.memberId });\n        toast('房间数据已删除');\n      }\n    };\n    renderModal();\n    return;\n  }\n\n  if (act === 'save-room-edit'){\n    const roomId = modal && modal.roomId;\n    const rooms = (S.session.rooms || []).map(room => {\n      if (room.id !== roomId) return { ...room };\n      const startText = document.getElementById('edit-room-start').value;\n      return {\n        ...room,\n        roomNo: document.getElementById('edit-room-no').value.trim() || room.roomNo,\n        title: document.getElementById('edit-room-title').value.trim() || '活动报名',\n        venue: document.getElementById('edit-room-venue').value.trim() || '待定',\n        startAt: startText ? new Date(startText).getTime() : room.startAt,\n        durationMin: Math.max(30, Math.min(720, parseInt(document.getElementById('edit-room-duration').value, 10) || room.durationMin)),\n        deadlineMin: Math.max(0, Math.min(2880, (parseFloat(document.getElementById('edit-room-deadline').value) || 0) * 60))\n      };\n    });\n    modal = null;\n    renderModal();\n    commit({ t: 'settings', patch: { rooms } });\n    toast('房间信息已保存');\n    return;\n  }\n\n  if (act === 'move-table'){\n    if (!mePlayer()) { toast('先报名才能换房间'); return; }\n    modal = { type: 'move' };\n    renderModal();\n    return;\n  }\n\n  if (act === 'move-to'){\n    const roomId = el.dataset.id;\n    const current = mePlayer() && mePlayer().roomId;\n    if (!roomId || roomId === current) return;\n    modal = null;\n    renderModal();\n    commit({ t: 'move', memberId: S.memberId, roomId });\n    const room = roomOf(S, roomId);\n    toast('已换到' + (room ? roomName(S, S.session.rooms.indexOf(room)) : '目标房间'));\n    return;\n  }\n\n  if (act === 'pick'){\n    S.memberId = el.dataset.id;\n    save();\n    modal = null; renderModal(); render();\n    toast('好，你是 ' + (memberOf(S, S.memberId) || {}).name);\n    return;\n  }\n\n  if (act === 'toggle'){\n    if (!meM()){ askWho(); return; }\n    if (mePlayer()){\n      const room = roomOf(S, mePlayer().roomId);\n      const late = room && Date.now() > deadlineOf(room);\n      const going = room && Date.now() >= room.startAt;\n      if (late){\n        modal = {\n          type: 'confirm',\n          title: going ? '这局已经开台了' : '已经过报名截止时间',\n          desc: going\n            ? '现在退出会记一次放鸽子，信用 -10。确定要退吗？'\n            : '现在取消会扣 10 点信用分。确定要取消吗？自己找个人替你也行。',\n          okText: '仍然退出', danger: true,\n          onOk: () => { modal = null; renderModal(); commit({ t: 'leave', memberId: S.memberId }); toast('已退出，信用 -10'); }\n        };\n        renderModal();\n      } else {\n        commit({ t: 'leave', memberId: S.memberId });\n        toast('已取消报名');\n      }\n    }\n    return;\n  }\n\n  if (act === 'settings'){ modal = { type: 'settings' }; renderModal(); return; }\n\n  if (act === 'save-settings'){\n    const rooms = (S.session.rooms || []).map((room, i) => {\n      const startText = document.querySelector('[data-room-start=\"' + i + '\"]').value;\n      return {\n        id: room.id,\n        roomNo: document.querySelector('[data-room-no=\"' + i + '\"]').value.trim() || String(i + 1),\n        title: document.querySelector('[data-room-title=\"' + i + '\"]').value.trim() || '活动报名',\n        venue: document.querySelector('[data-room-venue=\"' + i + '\"]').value.trim() || '待定',\n        startAt: startText ? new Date(startText).getTime() : room.startAt,\n        durationMin: Math.max(30, Math.min(720, parseInt(document.querySelector('[data-room-duration=\"' + i + '\"]').value, 10) || 180)),\n        deadlineMin: Math.max(0, Math.min(2880, (parseFloat(document.querySelector('[data-room-deadline=\"' + i + '\"]').value) || 0) * 60))\n      };\n    });\n    modal = null; renderModal();\n    commit({ t: 'settings', patch: { rooms } });\n    toast('已保存');\n    return;\n  }\n\n  if (act === 'roster'){\n    modal = { type: 'roster', list: S.members.map(m => ({ ...m })) };\n    renderModal();\n    return;\n  }\n  if (act === 'roster-add'){\n    syncRoster();\n    modal.list.push({ id: rid('m'), name: '', emoji: '', color: '' });\n    renderModal();\n    return;\n  }\n  if (act === 'roster-del'){\n    syncRoster();\n    modal.list.splice(Number(el.dataset.i), 1);\n    renderModal();\n    return;\n  }\n  if (act === 'roster-save'){\n    syncRoster();\n    const list = modal.list\n      .map(m => ({ ...m, name: String(m.name || '').trim().slice(0, 8) }))\n      .filter(m => m.name);\n    if (!list.length){ toast('至少要留一个人'); return; }\n    const lost = S.memberId && !list.some(m => m.id === S.memberId);\n    if (lost) S.memberId = null;\n    modal = null; renderModal();\n    commit({ t: 'members', list });\n    toast('名单已保存（' + list.length + ' 人）');\n    if (!S.memberId) askWho();\n    return;\n  }\n\n  if (act === 'add-self'){\n    modal = { type: 'addself' };\n    renderModal();\n    setTimeout(() => { const i = document.getElementById('in-name'); if (i) i.focus(); }, 60);\n    return;\n  }\n  if (act === 'addself-ok'){\n    const name = document.getElementById('in-name').value.trim().slice(0, 8);\n    if (!name){ toast('先输个名字'); return; }\n    const id = rid('m');\n    const list = S.members.concat([{ id, name, emoji: '', color: avatarColor(name) }]);\n    S.memberId = id;\n    modal = null; renderModal();\n    commit({ t: 'members', list });\n    render();\n    toast('加好了，你是 ' + name);\n    return;\n  }\n\n  if (act === 'confirm-ok'){\n    const fn = modal && modal.onOk;\n    modal = null;\n    renderModal();\n    if (fn) fn();\n    return;\n  }\n\n  if (act === 'open-score'){\n    if (!seated().length){ toast('还没人报名'); return; }\n    modal = { type: 'scores' };\n    renderModal();\n    return;\n  }\n\n  if (act === 'score-table'){\n    modal = { type: 'score', roomId: el.dataset.id };\n    renderModal();\n    return;\n  }\n\n  if (act === 'score-room'){\n    modal = { type: 'score', roomId: el.dataset.id };\n    renderModal();\n    return;\n  }\n\n  if (act === 'close-scores'){\n    modal = { type: 'scores' };\n    renderModal();\n    return;\n  }\n\n  if (act === 'unscore'){\n    const id = el.dataset.id;\n    commit({ t: 'unscore', id });\n    modal = { type: 'scores' };\n    renderModal();\n    toast('这条成绩删掉了');\n    return;\n  }\n\n  if (act === 'save-score'){\n    const room = roomRecordOf(S, modal.roomId);\n    const t = room\n      ? (roomOf(S, room.id) ? playersForRoom(S, room) : (room.players || []).filter(player => !player.cancelled))\n      : [];\n    const results = t.map((p, i) => ({\n      memberId: p.memberId,\n      score: parseInt(document.querySelector('[data-score=\"' + i + '\"]').value, 10) || 0\n    }));\n    const sum = results.reduce((a, r) => a + r.score, 0);\n    commit({ t: 'score', id: rid('h'), roomId: room && room.id, results });\n    modal = { type: 'scores' };\n    renderModal();\n    toast(sum === 0 ? `${room ? room.roomNo : '房间'}记好了` : `${room ? room.roomNo : '房间'}记好了（合计 ${sum > 0 ? '+' : ''}${sum}，不是 0）`);\n    return;\n  }\n\n  if (act === 'share'){\n    const all = activePlayers(S);\n    const names = all.map(p => (memberOf(S, p.memberId) || {}).name).filter(Boolean).join('、');\n    const text = [\n      `【聚会/活动报名】共 ${roomCount(S)} 个房间`,\n      ...((S.session.rooms || []).map(room => `${room.roomNo}｜${room.title}｜${room.venue}｜${fmtFull(room.startAt)}`)),\n      `已报名 ${all.length} 人：${names || '还没有人'}`,\n      waiting().length ? `候补 ${waiting().length} 人` : '还有空位可以报名',\n      `报名点这里 👉 ${location.href.startsWith('http') ? location.href : '（部署后的链接）'}`,\n    ].join('\\n');\n    modal = { type: 'share', text };\n    renderModal();\n    return;\n  }\n\n  if (act === 'copy-share'){\n    const ta = document.getElementById('share-txt');\n    ta.select();\n    let ok = false;\n    try { ok = document.execCommand('copy'); } catch (e) {}\n    if (!ok && navigator.clipboard){ navigator.clipboard.writeText(ta.value); ok = true; }\n    toast(ok ? '复制好了，去群里粘贴' : '复制失败，手动长按选中');\n    return;\n  }\n});\n\ndocument.addEventListener('keydown', e => {\n  if (e.key === 'Enter' && modal && modal.type === 'addself'){\n    document.querySelector('[data-act=\"addself-ok\"]').click();\n  }\n});\n\ndocument.addEventListener('input', e => {\n  if (modal && modal.type === 'score' && e.target.matches && e.target.matches('[data-score]')) updateSum();\n});\n\n/* 每秒刷新倒计时 */\nsetInterval(() => {\n  if (tab !== 'signup' || modal) return;\n  const before = JSON.stringify([...(S.session.rooms || []).map(room => room.id), ...(S.archivedRooms || []).map(room => room.id)]);\n  normalizeState(S, Date.now());\n  const after = JSON.stringify([...(S.session.rooms || []).map(room => room.id), ...(S.archivedRooms || []).map(room => room.id)]);\n  if (before !== after) save();\n  render();\n}, 1000);\n\n/* ===================== 启动 ===================== */\nasync function boot(){\n  if (/^https?:$/.test(location.protocol)){\n    try {\n      const d = await apiGet();\n      ONLINE = true;\n      adopt(d);\n    } catch (e) {\n      ONLINE = false;\n    }\n  }\n  render();\n  if (!S.memberId) askWho();\n  if (ONLINE){\n    setInterval(poll, 5000);\n    document.addEventListener('visibilitychange', () => { if (!document.hidden) poll(); });\n  }\n}\n\nasync function poll(){\n  if (modal) return;\n  // 还有没发出去的动作，先把它们补上，别用服务器旧数据盖掉本地\n  if (outbox.length || flushing){ flush(); return; }\n  try {\n    const d = await apiGet();\n    if (d.updatedAt !== S.updatedAt) adopt(d);\n  } catch (e) {}\n}\n\nboot();\n</script>\n</body>\n</html>\n";

const corsHeaders = {
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'GET, POST, OPTIONS',
  'access-control-allow-headers': 'content-type',
  'cache-control': 'no-store'
};

const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...corsHeaders }
  });

async function readState(env, key) {
  const raw = await env.MJ_KV.get(key);
  if (raw) {
    try {
      const state = normalizeState(JSON.parse(raw));
      await env.MJ_KV.put(key, JSON.stringify(state));
      return state;
    } catch (e) { /* 坏数据就当空的 */ }
  }
  return null;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const g = url.searchParams.get('g') || 'main';
    const key = 'g:' + g;

    try {
      if (request.method === 'OPTIONS' && url.pathname.startsWith('/api/')) {
        return new Response(null, { status: 204, headers: corsHeaders });
      }

      if (url.pathname === '/api/state') {
        if (request.method !== 'GET') return json({ error: 'method not allowed' }, 405);
        let st = await readState(env, key);
        if (!st) {
          st = defaultState();
          await env.MJ_KV.put(key, JSON.stringify(st));
        }
        return json(st);
      }

      if (url.pathname === '/api/op') {
        if (request.method !== 'POST') return json({ error: 'method not allowed' }, 405);
        let op;
        try { op = await request.json(); } catch (e) { return json({ error: 'bad json' }, 400); }
        const st = (await readState(env, key)) || defaultState();
        const next = applyOp(st, op, Date.now());
        await env.MJ_KV.put(key, JSON.stringify(next));
        return json(next);
      }

      if (url.pathname.startsWith('/api/')) return json({ error: 'not found' }, 404);

      return new Response(PAGE, {
        headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' }
      });
    } catch (e) {
      return json({ error: String((e && e.message) || e) }, 500);
    }
  }
};
